        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                return

        for i in range(3):
            piece = pieces[current_piece_index[i]]
            piece.y += 1
            if check_collision(boards[i], piece):
                piece.y -= 1
                merge(boards[i], piece)
                scores[i] += clear_lines(boards[i])
