        self.current_pos = [0, GRID_WIDTH // 2 - 1]

    def clear_lines(self):
        lines_to_clear = [i for i in range(GRID_HEIGHT) if all(self.grid[i])]
        for i in lines_to_clear:
            del self.grid[i]
            self.grid.insert(0, [0] * GRID_WIDTH)
            self.score += 1

